def solution(n, parents, perm):
	res = [-1 for _ in range(len(parents))]
	temp = 0
	for (i, b) in enumerate(parents):
		if i == b:
			temp = i
			break
	res[temp] = 0
	if perm[0] != temp:
		print('-1')
		return
	for (i, p) in enumerate(perm):
		if res[parents[p]] == -1:
			print('-1')
			return
		res[p] = i
	print(' '.join((str(res[p] - res[parents[p]]) for p in range(n))))
t = int(input())
for _ in range(t):
	n = int(input())
	parents = [int(x) - 1 for x in input().split()]
	perm = [int(x) - 1 for x in input().split()]
	solution(n, parents, perm)
